import urllib.parse, urllib.request, json, sys, time

def srch(q, rows=120):
    url = "https://archive.org/advancedsearch.php?" + urllib.parse.urlencode({
        'q': q, 'rows': rows, 'page':1, 'output':'json'}) + \
        "&fl[]=identifier&fl[]=title&fl[]=creator&fl[]=year&fl[]=language"
    try:
        d = json.load(urllib.request.urlopen(url, timeout=60))
        return d['response']['docs']
    except Exception as e:
        print("ERR", q, e, file=sys.stderr); return []

queries = [
 'title:("lake district") AND mediatype:texts AND date:[1600-01-01 TO 1901-01-01]',
 'title:("english lakes") AND mediatype:texts AND date:[1600-01-01 TO 1901-01-01]',
 'title:("the lakes") AND (Cumberland OR Westmorland OR Westmoreland) AND mediatype:texts AND date:[1600-01-01 TO 1901-01-01]',
 'title:(lakeland) AND mediatype:texts AND date:[1600-01-01 TO 1901-01-01]',
 'title:(Windermere OR Keswick OR Grasmere OR Ambleside OR Coniston OR Borrowdale OR Skiddaw OR Helvellyn OR Derwentwater OR Ullswater) AND mediatype:texts AND date:[1600-01-01 TO 1901-01-01]',
 'title:(Cumberland OR Westmorland OR Westmoreland OR Furness) AND mediatype:texts AND date:[1600-01-01 TO 1901-01-01] AND (history OR antiquities OR guide OR tour OR description OR flora OR geology)',
]
seen={}
for q in queries:
    for d in srch(q):
        seen[d['identifier']]=d
    time.sleep(1)
print(len(seen))
for k,v in sorted(seen.items(), key=lambda x: str(x[1].get('year'))):
    print("\t".join([str(v.get('year')), k, str(v.get('creator'))[:45], str(v.get('title'))[:85]]))
EOF
