import json, urllib.request, sys, concurrent.futures

def meta(idf):
    try:
        with urllib.request.urlopen("https://archive.org/metadata/"+idf, timeout=90) as r:
            return json.load(r)
    except Exception as e:
        return {"_err":str(e)}

def pick(idf):
    m = meta(idf)
    if "_err" in m or not m.get("files"):
        return idf, None, None, m.get("_err","no-files"), None
    files = m["files"]
    md = m.get("metadata",{})
    byname = {f["name"]: f for f in files}
    # preference: djvu.txt, then *_text.pdf / .pdf, then abbyy gz
    cand = None
    for f in files:
        n=f["name"]
        if n.endswith("_djvu.txt"): cand=n; break
    if not cand:
        for f in files:
            if f["name"].endswith(".txt") and f.get("format","").lower() in ("text","djvutxt","plain text"): cand=f["name"]; break
    if not cand:
        for f in files:
            if f["name"].endswith("_text.pdf"): cand=f["name"]; break
    if not cand:
        for f in files:
            if f["name"].endswith(".pdf"): cand=f["name"]; break
    size = byname[cand].get("size") if cand else None
    return idf, cand, md.get("title"), md.get("date") or md.get("year"), size

ids=[l.strip() for l in open("cand_list.txt") if l.strip()]
with concurrent.futures.ThreadPoolExecutor(max_workers=8) as ex:
    for idf,f,t,d,s in ex.map(pick, ids):
        print("\t".join([idf, str(f), str(s), str(d), str(t)[:60]]))
EOF
python3 verify.py > verified.tsv 2>&1; grep -c . verified.tsv; echo "--- MISSING TEXT ---"; awk -F'\t' '$2=="None"' verified.tsv

