import json, urllib.request, concurrent.futures, time
rows=[json.loads(l) for l in open('texts.jsonl')]
def get(r):
    u=r['download_url']
    for attempt in range(4):
        try:
            req=urllib.request.Request(u); req.add_header('Range','bytes=0-4095')
            with urllib.request.urlopen(req,timeout=240) as resp:
                d=resp.read()
                if resp.status in (200,206) and len(d)>1000 and 'text' in resp.headers.get('Content-Type',''):
                    return r,'OK',len(d),d[:0]
                last=(resp.status,len(d),resp.headers.get('Content-Type'))
        except Exception as e:
            last=str(e)
        time.sleep(3+attempt*5)
    return r,'FAIL',last,None
bad=[]
with concurrent.futures.ThreadPoolExecutor(max_workers=5) as ex:
    for r,st,info,_ in ex.map(get,rows):
        if st!='OK': bad.append((r['year'],r['title'][:45],info))
for b in bad: print("FAIL",b)
print(f"\nverified {len(rows)-len(bad)}/{len(rows)} URLs return live text")
EOF
python3 final_check.py

